// Protocol port tests. Fixtures are generated by the Python reference (tests/fixtures.json at the
// repo root) so the Dart and Python implementations are checked against identical vectors.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:coolbar/protocol/blufi.dart';
import 'package:coolbar/protocol/commands.dart';
import 'package:flutter_test/flutter_test.dart' hide matches;

Uint8List _hex(String h) => Uint8List.fromList([for (var i = 0; i < h.length; i += 2) int.parse(h.substring(i, i + 2), radix: 16)]);
String _toHex(List<int> b) => b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  final fx = jsonDecode(File('../tests/fixtures.json').readAsStringSync()) as Map<String, dynamic>;

  test('crc16 vectors', () {
    for (final v in fx['crc16'] as List) {
      expect(crc16be(_hex(v[0] as String)), v[1]);
    }
  });

  test('aes-cfb128 vector and roundtrip', () {
    final a = fx['aes'] as Map<String, dynamic>;
    final key = _hex(a['key']), plain = _hex(a['plain']);
    final enc = aesCfb(key, a['seq'] as int, plain, encrypt: true);
    expect(_toHex(enc), a['cipher']);
    expect(aesCfb(key, a['seq'] as int, enc, encrypt: false), plain);
  });

  test('fragmentation follows EspBlufi rules', () async {
    final frames = <Uint8List>[];
    final bf = BluFi(mtu: 23, writer: (b) async => frames.add(b));
    final payload = List<int>.generate(60, (i) => i);
    await bf.send(pktData, dataCustom, payload);
    expect(frames.every((f) => f.length <= 20), isTrue);
    expect([for (final f in frames) f[2]], List.generate(frames.length, (i) => i));
    for (var i = 0; i < frames.length - 1; i++) {
      expect(frames[i][1] & fcFrag, isNot(0));
    }
    expect(frames.last[1] & fcFrag, 0);
    final body = <int>[];
    for (var i = 0; i < frames.length - 1; i++) {
      body.addAll(frames[i].sublist(6, 4 + frames[i][3]));
    }
    body.addAll(frames.last.sublist(4, 4 + frames.last[3]));
    expect(body, payload);
  });

  test('reassembly drops a frame whose length disagrees with the declared total', () async {
    final bf = BluFi(writer: (_) async {});
    final got = <Frame>[];
    bf.frames.listen(got.add);
    bf.onNotify([dataCustom << 2 | 1, fcFrag, 0, 5, 5, 0, 1, 2, 3]);
    bf.onNotify([dataCustom << 2 | 1, 0, 1, 3, 4, 5, 6]);
    await Future.delayed(const Duration(milliseconds: 20));
    expect(got, isEmpty);
  });

  test('encode follows the app rules', () {
    const base = ACState(power: true, temp: 24, mode: 'cool', fan: 'auto');
    expect(encode(base.copyWith(temp: 25), base), {'stemp': '25.0'});
    expect(encode(base.copyWith(power: false), base), {'pow': 0});
    expect(encode(base.copyWith(mode: 'dry'), base), {'mode': {'value': 3, 'stemp': '24.0', 'fspd': 7}});
    expect(encode(base.copyWith(conv: 2), base), {'eco': {'value': 2}});
    expect(encode(base.copyWith(vswing: 3), base), {'vswing': 3});
  });

  test('decode status fixture', () {
    final st = decode((fx['status'] as Map).cast<String, dynamic>(), null)!;
    expect(st.power, isTrue);
    expect(st.temp, 16);
    expect(st.mode, 'cool');
    expect(st.fan, 'auto');
    expect(st.ambient, 24.5);
    expect(st.vswing, swingAuto);
    expect(st.display, isTrue);
  });

  test('matches handles the object form and rejects garbage', () {
    final status = (fx['status'] as Map).cast<String, dynamic>();
    expect(matches({'mode': {'value': 2, 'stemp': '99.0', 'fspd': 1}}, status), isTrue);
    expect(matches({'stemp': '17.0'}, status), isFalse);
    expect(matches({'pow': 1}, {...status, 'pow': 6, 'stemp': '357.9'}), isFalse);
  });
}
